import subprocess
import pandas as pd
import matplotlib.pyplot as plt
def task_func(script_path, output_file_path):
    try:
        result = subprocess.run(['python', script_path], capture_output=True)
        if result.returncode != 0:
            raise ValueError("Script failed to execute")
    except Exception:
        raise ValueError("Script failed to execute")

    try:
        df = pd.read_csv(output_file_path)
        if len(df.columns) != 2:
            raise ValueError("CSV must contain exactly 2 columns")
    except Exception:
        raise ValueError("CSV is invalid")

    ax = df.plot.bar(x=df.columns[0], y=df.columns[1])

    return df, ax
